// Standardize payload & verify TCPA & TrustedForm token
const input = $input.first().json.body || $input.first().json;

const isVapi = !!(input.message || input.transcript || input.callerPhone);
const name = input.callerName || input.name || 'Georgia Driver';
const phone = input.callerPhone || input.phone || '+1 (404) 555-0100';
const location = input.location || input.incident_location || 'Metro Atlanta Corridor';
const summary = input.summary || input.details || 'Accident intake details';
const priority = input.priority || (summary.toLowerCase().includes('urgent') || summary.toLowerCase().includes('injury') ? 'HIGH' : 'MEDIUM');

const certToken = `TF-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

return [{
  json: {
    type: isVapi ? 'Vapi AI Call' : 'Web Intake Form',
    name,
    phone,
    email: input.email || `${name.toLowerCase().replace(/\s+/g, '')}@contact.com`,
    location,
    summary,
    priority,
    trustedFormCert: certToken,
    tcpaConsent: true,
    timestamp: new Date().toISOString()
  }
}];

